WITH gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) > INTERVAL 30 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM transactions), sessions_transactions AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT CASE WHEN session_start_flag >= 1 THEN 'HIGH' ELSE 'LOW' END AS session_start_flag_tier, account_id, ROUND(AVG(session_start_flag), 2) AS avg_session_start_flag, ROUND(AVG(island_id), 2) AS avg_island_id, SUM(CASE WHEN txn_type = 'FEE' THEN island_id ELSE 0 END) AS fee_island_id, ROUND(SUM(island_id) / NULLIF(COUNT(CASE WHEN merchant = 'Starbucks' THEN 1 END), 0), 2) AS island_id_per_starbucks, MAX(txn_time) AS last_seen, PERCENTILE_APPROX(session_start_flag, 0.95) AS session_start_flag_p95 FROM sessions_transactions GROUP BY session_start_flag_tier, account_id HAVING PERCENTILE_APPROX(session_start_flag, 0.95) < 1000000;
